def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # If opponent opened with D, assume defector and defect forever.
    if history[0][1] == 'D':
        return 'D'

    # Chronic defector detection
    opp_coops = sum(1 for _, o in history if o == 'C')
    if n > 10 and opp_coops / n < 0.2:
        return 'D'

    if n < 10:
        return 'C'
    if n == 10 or n == 20:
        return 'D'
    if n >= 95:
        return 'D'

    my_defections = 0
    punish_count = 0
    for i in range(n):
        me, opp = history[i]
        if me == 'D':
            my_defections += 1
        if i < n - 1 and me == 'D' and history[i+1][1] == 'D':
            punish_count += 1

    if my_defections > 2 and punish_count == 0:
        p_defect = 1.0
    else:
        q = punish_count / my_defections if my_defections > 0 else 0.0
        p_defect = max(0.0, min(1.0, (2.0/3.0 - q) * 2.0))

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'C':
            return 'D' if rng.random() < 0.9 else 'C'
        else:
            return 'C' if rng.random() < 0.7 else 'D'
    else:
        if rng.random() < p_defect:
            return 'D'
        else:
            return 'C'
